// 通用 JSON 配置文件读写 + JSONL 追加原语 —— application 层。
//
// 框架级配置管理:不针对 settings.json/models.json 专用,而是通用的"读/写任意 JSON 文件"。
// 路径由 shell 注入(~ 已展开为绝对路径),不 import electron。
// 写用 proper-lockfile 防并发撕裂,深合并 or 整份覆盖由 mergeMode 控制。
//
// withDirLock 是各 store 共用的"锁目录 → fn → 释放"原语(消除 5 处重复 lockfile 模板),
// 也是"写串行化"的唯一实现点:进程内 per-dir 队列(消灭同进程锁竞争,ELOCKED 根因修复)
// + proper-lockfile 跨进程锁,两层都在这一处——调用方不自造队列(config-store 的
// writeQueues 已收敛到此并删除;设计 docs/design/dir-write-queue.md)。
// appendJsonlLine 是 JSONL 追加原语(同一把目录锁,尾字节补换行),服务 session 文件等
// append-only 文件;条目形状是内容层的事,原语中性(设计:docs/design/session-jsonl-append.md)。
import { closeSync, existsSync, mkdirSync, openSync, readFileSync, readSync, statSync } from "node:fs";
import { appendFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import * as lockfile from "proper-lockfile";
import { deepMergeJson } from "./json-merge";

/** 进程内 per-dir 写队列:串行链尾 Promise(错误已吞视图,不断链)。
 *  key 是归一化绝对路径(resolve),防同一目录因写法不同碎成两条队列;链跑空即删 entry。 */
const dirWriteQueues = new Map<string, Promise<void>>();

/**
 * 锁目录执行 fn,串行化并发写。两层结构(设计 docs/design/dir-write-queue.md):
 * - 进程内层:per-dir 串行队列——同进程的写按目录排队逐个执行,不再有同进程的两个
 *   请求同时抢同一把 proper-lockfile 锁(ELOCKED 的根因就在此层消灭)。
 * - 跨进程层:proper-lockfile 目录锁(stale 5s)——稳定版与 dev 版共享 ~/.pi/agent,
 *   两个 app 实例可能同写一目录;retries 仍兜跨进程竞争。
 * 锁目录而非文件:首次写时文件可能不存在,锁文件会 ENOENT;锁已 mkdir 的目录最稳。
 * config-store/models-store/pi-settings-store/session-scanner/skill-toggle 共用此原语。
 *
 * 契约:非重入。fn 内嵌套同目录 withDirLock 会在队列里死锁(嵌套调用排在外层之后,
 * 外层等内层完成才能出队,永远等不到)。现有调用点均无嵌套;未来需要嵌套时把内层
 * 纯 fn 提出去复用,不要套锁。
 */
export async function withDirLock<T>(dir: string, fn: () => Promise<T>): Promise<T> {
  const key = resolve(dir);
  const prev = dirWriteQueues.get(key) ?? Promise.resolve();
  const run = prev.then(async () => {
    let release: (() => Promise<void>) | null = null;
    try {
      release = await lockfile.lock(dir, {
        stale: 5000,
        retries: { retries: 3, factor: 2, minTimeout: 100, maxTimeout: 500, randomize: true },
      });
      return await fn();
    } finally {
      if (release) await release();
    }
  });
  // 队列视图吞错续跑(单任务失败不断链);调用方视图拿 run,原错照冒。
  const chained = run.then((): void => undefined, (): void => undefined);
  // 空闲清理:链settled 后若 Map entry 仍指自己则删(有新写入时已指向新尾,不删)。
  void chained.then(() => {
    if (dirWriteQueues.get(key) === chained) dirWriteQueues.delete(key);
  });
  dirWriteQueues.set(key, chained);
  return run;
}
